shapes.code:
struct Rectangle {
	width  int
	height int
}

struct Triangle {
	base   int
	height int
}

// A sum type: a Shape is exactly one of these structs.
type Shape = Rectangle | Triangle

fn (s Shape) area() int {
	// `match` must cover every variant; inside a branch `s` is smart-cast.
	return match s {
		Rectangle { s.width * s.height }
		Triangle { s.base * s.height / 2 }
	}
}

fn main() {
	shapes := [Shape(Rectangle{3, 4}), Triangle{10, 3}]
	for s in shapes {
		println('${s.type_name()}: ${s.area()}')
	}
}

