import strconv

// `!int` is a result: an int, or an error the caller must handle.
fn parse_age(s string) !int {
	n := strconv.atoi(s)! // a trailing `!` passes the error up
	if n > 150 {
		return error('${n} is out of range')
	}
	return n
}

// `?string` is an option: a string or `none`. There is no null.
fn nickname(name string) ?string {
	return if name == 'Robert' { 'Bob' } else { none }
}

fn main() {
	mut total := 0 // immutable unless declared `mut`
	for s in ['42', 'abc', '200', '7'] {
		total += parse_age(s) or {
			println('skipped ${s}: ${err}')
			continue
		}
	}
	println('total: ${total}')
	println(nickname('Robert') or { 'no nickname' })
	println(nickname('Alice') or { 'no nickname' })
}
